#include "studio_selection.h"
#include "palette_math.h"
#include <algorithm>
#include <cmath>
namespace studio {
namespace {
bool dimensions(int w,int h){return w>0&&h>0&&w<=8192&&h<=8192&&(size_t)w*h<=4*1024*1024;}
PixelSelection bounded(int w,int h,std::vector<unsigned char> mask){PixelSelection s;if(!dimensions(w,h)||mask.size()!=(size_t)w*h)return s;int x0=w,y0=h,x1=-1,y1=-1;for(int y=0;y<h;++y)for(int x=0;x<w;++x)if(mask[(size_t)y*w+x]){x0=std::min(x0,x);y0=std::min(y0,y);x1=std::max(x1,x);y1=std::max(y1,y);}if(x1<0)return s;s.valid=true;s.x=x0;s.y=y0;s.w=x1-x0+1;s.h=y1-y0+1;s.canvas_w=w;s.canvas_h=h;s.mask=std::move(mask);return s;}
}
bool PixelSelection::contains(int px,int py)const{if(!valid||px<x||py<y||px-x>=w||py-y>=h)return false;if(mask.empty())return true;return px>=0&&py>=0&&px<canvas_w&&py<canvas_h&&mask.size()==(size_t)canvas_w*canvas_h&&mask[(size_t)py*canvas_w+px]!=0;}
PixelSelection selection_from_mask(int width,int height,std::vector<unsigned char> mask){return bounded(width,height,std::move(mask));}
bool PixelSelection::fits(int width,int height)const{if(!valid)return true;if(!dimensions(width,height)||x<0||y<0||w<1||h<1||w>width||h>height||x>width-w||y>height-h)return false;return mask.empty()||(canvas_w==width&&canvas_h==height&&mask.size()==(size_t)width*height);}
int PixelSelection::count()const{if(!valid)return 0;if(mask.empty())return w*h;return (int)std::count_if(mask.begin(),mask.end(),[](unsigned char v){return v!=0;});}
PixelSelection rectangle_selection(int width,int height,int x,int y,int w,int h){if(!dimensions(width,height)||w<=0||h<=0)return {};int left=std::clamp(x,0,width),top=std::clamp(y,0,height),right=(int)std::clamp((long long)x+w,0LL,(long long)width),bottom=(int)std::clamp((long long)y+h,0LL,(long long)height);if(right<=left||bottom<=top)return {};return {true,left,top,right-left,bottom-top};}
PixelSelection wand_selection(const IMG &im,const PAL &pal,int x,int y,int tolerance,bool contiguous){if(!dimensions(im.w,im.h)||!im.data_p||x<0||y<0||x>=im.w||y>=im.h||!pal.data_p||pal.numc<1||pal.numc>256)return {};int stride=(im.w+3)&~3;auto pixels=(const unsigned char *)im.data_p;int seed=pixels[y*stride+x];if(seed>=pal.numc)return {};std::vector<unsigned char> mask((size_t)im.w*im.h);PAL palette=pal;auto matches=[&](int xx,int yy){int value=pixels[yy*stride+xx];return value<pal.numc&&PaletteIndexWithinTolerance(&palette,seed,value,std::clamp(tolerance,0,255));};
    if(contiguous){std::vector<int> todo{y*im.w+x};mask[y*im.w+x]=1;while(!todo.empty()){int p=todo.back();todo.pop_back();int xx=p%im.w,yy=p/im.w;const int dx[]={-1,1,0,0},dy[]={0,0,-1,1};for(int k=0;k<4;++k){int nx=xx+dx[k],ny=yy+dy[k];if(nx>=0&&ny>=0&&nx<im.w&&ny<im.h&&!mask[ny*im.w+nx]&&matches(nx,ny)){mask[ny*im.w+nx]=1;todo.push_back(ny*im.w+nx);}}}}
    else for(int yy=0;yy<im.h;++yy)for(int xx=0;xx<im.w;++xx)mask[yy*im.w+xx]=matches(xx,yy)?1:0;return bounded(im.w,im.h,std::move(mask));
}
PixelSelection lasso_selection(int width,int height,const std::vector<SelectionPoint> &points){if(!dimensions(width,height)||points.size()<3||points.size()>4096)return {};for(auto p:points)if(!std::isfinite(p.x)||!std::isfinite(p.y)||p.x<0||p.y<0||p.x>width||p.y>height)return {};std::vector<unsigned char> mask((size_t)width*height);float left=(float)width,right=0,top=(float)height,bottom=0;for(auto p:points){left=std::min(left,p.x);right=std::max(right,p.x);top=std::min(top,p.y);bottom=std::max(bottom,p.y);}for(int y=(int)top;y<std::min(height,(int)std::ceil(bottom));++y){float py=y+.5f;std::vector<float> crossings;for(size_t i=0,j=points.size()-1;i<points.size();j=i++){auto a=points[j],b=points[i];if((a.y>py)!=(b.y>py))crossings.push_back(a.x+(py-a.y)*(b.x-a.x)/(b.y-a.y));}std::sort(crossings.begin(),crossings.end());for(size_t k=1;k<crossings.size();k+=2){int x0=std::max(0,(int)std::ceil(crossings[k-1]-.5f)),x1=std::min(width,(int)std::ceil(crossings[k]-.5f));for(int x=x0;x<x1;++x)mask[(size_t)y*width+x]=1;}}return bounded(width,height,std::move(mask));}
PixelSelection opaque_selection(const IMG &im){if(!dimensions(im.w,im.h)||!im.data_p)return {};std::vector<unsigned char> mask((size_t)im.w*im.h);int stride=(im.w+3)&~3;for(int y=0;y<im.h;++y)for(int x=0;x<im.w;++x)mask[y*im.w+x]=((unsigned char *)im.data_p)[y*stride+x]?1:0;return bounded(im.w,im.h,std::move(mask));}
PixelSelection combine_selection(const PixelSelection &base,const PixelSelection &added,SelectionOp op,int width,int height){if(!dimensions(width,height)||!base.fits(width,height)||!added.fits(width,height))return {};if(op==SelectionOp::Replace)return added;std::vector<unsigned char> mask((size_t)width*height);for(int y=0;y<height;++y)for(int x=0;x<width;++x){bool a=base.contains(x,y),b=added.contains(x,y);mask[y*width+x]=(op==SelectionOp::Add?a||b:op==SelectionOp::Subtract?a&&!b:a&&b)?1:0;}return bounded(width,height,std::move(mask));}
PixelSelection invert_selection(const PixelSelection &s,int width,int height){return combine_selection(rectangle_selection(width,height,0,0,width,height),s,SelectionOp::Subtract,width,height);}
PixelSelection translate_selection(const PixelSelection &s,int dx,int dy,int width,int height){if(!dimensions(width,height)||!s.valid||!s.fits(width,height))return {};std::vector<unsigned char> mask((size_t)width*height);for(int y=s.y;y<s.y+s.h;++y)for(int x=s.x;x<s.x+s.w;++x)if(s.contains(x,y)){long long nx=(long long)x+dx,ny=(long long)y+dy;if(nx>=0&&ny>=0&&nx<width&&ny<height)mask[(size_t)ny*width+(size_t)nx]=1;}return bounded(width,height,std::move(mask));}
}
